mapper.select:
SELECT u.user_id, u.email, u.nickname, u.status, u.last_login_at, u.created_at, r.role_code as role, r.role_name, (SELECT COUNT(*) FROM CHAT_ROOM cr WHERE cr.user_id = u.user_id) as conversations, (SELECT COUNT(*) FROM COUNSEL_FEEDBACK cf JOIN MESSAGE m ON cf.message_id = m.message_id JOIN CHAT_ROOM cr ON m.chat_room_id = cr.chat_room_id WHERE cr.user_id = u.user_id) as feedbackCount, IFNULL((SELECT activity_score FROM USER_ACTIVITY_DAILY uad WHERE uad.user_id = u.user_id ORDER BY activity_date DESC LIMIT 1), 0) as attendance FROM USER u LEFT JOIN USER_ROLE ur ON u.user_id = ur.user_id LEFT JOIN ROLE r ON ur.role_id = r.role_id
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%'))
AND r.role_code = #{roleCode}
AND u.status = #{status}
ORDER BY u.created_at DESC

SELECT s.support_id, s.user_id, u.nickname as userNickname, s.title, s.content, s.status, s.created_at, sr.reason_name as category, CASE WHEN sr.request_type = 'REPORT' THEN 'HIGH' ELSE 'MEDIUM' END as priority FROM SUPPORT s JOIN USER u ON s.user_id = u.user_id JOIN SUPPORT_REASON sr ON s.support_reason_id = sr.support_reason_id
AND s.status = #{status}
ORDER BY s.created_at DESC
